-- -----------------------------------
-- Table structure for `sites_siminfo`
-- -----------------------------------

DROP TABLE IF EXISTS `sites_siminfo`;
CREATE TABLE `sites_siminfo` (
  `id` int(6) NOT NULL AUTO_INCREMENT,
  `atmid` varchar(20) CHARACTER SET utf8 DEFAULT NULL,
  `simnnumber` varchar(20) CHARACTER SET utf8 DEFAULT NULL,
  `simowner` varchar(20) CHARACTER SET utf8 DEFAULT NULL,
  `status` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=4235 DEFAULT CHARSET=latin1;

